"""Validate external metadata only; raw packet/frame bytes stay opaque."""
import json,re
MAX=2**62-1
HEX=re.compile(r'(?:[0-9a-fA-F]{2})*\Z',re.ASCII)
def pairs(items):
    out={}
    for k,v in items:
        if k in out:raise ValueError('duplicate decoded key')
        out[k]=v
    return out
def num(x,limit=MAX):return type(x) is int and 0<=x<=limit
def shape(x,names):return type(x) is dict and x.keys()==set(names.split())
def hex_bytes(x,low=0,high=8*1024**2):
    if type(x) is not str or not HEX.fullmatch(x) or not low<=len(x)//2<=high:raise ValueError('hex')
    return bytes.fromhex(x)
def normalize(raw):
    if len(raw)>32*1024**2:raise ValueError('stdin cap')
    def bad(x):raise ValueError('noninteger/nonfinite')
    batch=json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_float=bad,parse_constant=bad)
    if not shape(batch,'traces') or type(batch['traces']) is not list or len(batch['traces'])>64:raise ValueError('batch')
    events=wire_bytes=local_ids=0;lines=[str(len(batch['traces']))]
    for t in batch['traces']:
        if not shape(t,'limits local peer received events'):raise ValueError('trace')
        a,b,c,d=t['limits'],t['local'],t['peer'],t['received']
        if not shape(a,'connection stream bidi uni cids') or not shape(b,'bidi uni cids') or not shape(c,'cid token') or not shape(d,'I H A'):raise ValueError('configuration')
        if not all(num(a[k]) for k in ['connection','stream']) or not all(num(x[k],2**60) for x in [a,b] for k in ['bidi','uni']):raise ValueError('limits')
        if not num(a['cids'],4096) or a['cids']<2:raise ValueError('CID limit')
        ids=b['cids']
        if type(ids) is not list or not 1<=len(ids)<=4096:raise ValueError('local CIDs')
        decoded=[hex_bytes(x,1,20) for x in ids]
        if len(set(decoded))!=len(decoded) or len({len(x) for x in decoded})!=1:raise ValueError('CID uniqueness/width')
        local_ids+=len(ids);peer=hex_bytes(c['cid'],1,20);token=hex_bytes(c['token'],16,16)
        if any(x is not None and not num(x) for x in d.values()):raise ValueError('received seed')
        if type(t['events']) is not list:raise ValueError('events')
        lines.append(' '.join(str(x) for x in [a['connection'],a['stream'],a['bidi'],a['uni'],a['cids'],b['bidi'],b['uni']]))
        lines.append(' '.join(x.hex() for x in decoded));lines.append(peer.hex()+' '+token.hex())
        lines.append(' '.join('-' if d[k] is None else str(d[k]) for k in ['I','H','A']))
        lines.append(str(len(t['events'])));events+=len(t['events'])
        for e in t['events']:
            if shape(e,'keys'):
                keys=e['keys']
                if type(keys) is not list or len(keys)>3 or any(type(k) is not str or k not in ['I','H','A'] for k in keys) or len(set(keys))!=len(keys):raise ValueError('keys')
                lines.append('K'+''.join(' '+k for k in keys))
            elif shape(e,'datagram'):
                dg=e['datagram']
                if not shape(dg,'wire auth') or type(dg['auth']) is not list or len(dg['auth'])>256:raise ValueError('datagram metadata')
                if any(x is not None and not num(x) for x in dg['auth']):raise ValueError('authentication annotation')
                wire=hex_bytes(dg['wire']);wire_bytes+=len(wire)
                lines.append('D '+(dg['wire'] or '-'))
                lines.append(' '.join('-' if x is None else str(x) for x in dg['auth']) or '-')
            else:raise ValueError('event')
    if events>8192 or wire_bytes>8*1024**2 or local_ids>16384:raise ValueError('structural caps')
    return ('\n'.join(lines)+'\n').encode('ascii')
